import { Router } from "express";

export const postsRouter = Router();

postsRouter.get("/", (req, res) => {
  const page = Number(req.query.page ?? 1);
  res.json({ page, items: [] });
});

postsRouter.get("/:id", (req, res) => {
  res.json({ id: req.params.id });
});

